	world, _ := suspensionGeometry(t)
	data, err := gameassets.Original.ReadFile("original/tire-slip-curve.bin")
	if err != nil {
		t.Fatal(err)
	}
	curve, err := NewContactCurve(data)
	if err != nil {
		t.Fatal(err)
	}
	for _, c := range cases {
		output := CalculateWheels(c.input, &curve, world)
		var data bytes.Buffer
		if err := binary.Write(&data, binary.BigEndian, output); err != nil {
			t.Fatal(err)
		}
		if got := fmt.Sprintf("%x", sha256.Sum256(data.Bytes())); got != c.digest {
			t.Fatalf("%s: got %+v (%s), want %s", c.name, output, got, c.digest)
		}
	}
